package tools.php.ast2cpg;
import java.io.*; import java.util.*; import ast.php.functionDef.FunctionDef; import ast.functionDef.ParameterList; import ast.php.functionDef.Parameter; import inputModules.csv.csvFuncExtractor.CSVFunctionExtractor; import cg.*; import cfg.*; import udg.*; import udg.php.useDefAnalysis.PHPASTDefUseAnalyzer; import udg.useDefGraph.UseDefGraph; import ddg.*; import ddg.DataDependenceGraph.DDG; import ddg.DefUseCFG.DefUseCFG; import misc.Pair;
public class ProbeGate11 { public static void main(String[] args)throws Exception{ Main.baseDir="."; CSVFunctionExtractor ex=new CSVFunctionExtractor(); ex.setInterpreters(new PHPCSVNodeInterpreter(),new PHPCSVEdgeInterpreter()); ex.initialize(new FileReader("nodes.csv"),new FileReader("rels.csv")); ASTToCFGConverter a=new ASTToCFGConverter(); a.setFactory(new PHPCFGFactory()); CFGToUDGConverter b=new CFGToUDGConverter(); b.setASTDefUseAnalyzer(new PHPASTDefUseAnalyzer()); CFGAndUDGToDefUseCFG c=new CFGAndUDGToDefUseCFG(); DDGCreator d=new DDGCreator(); HashSet<FunctionDef> roots=new HashSet<>(); FunctionDef r; while((r=(FunctionDef)ex.getNextFunction())!=null){roots.add(r); CFG cfg=a.convert(r); UseDefGraph u=b.convert(cfg); DefUseCFG du=c.convert(cfg,u); d.createForDefUseCFG(du);} for(FunctionDef root:roots)PHPCGFactory.addFunctionDef(root); PHPCGFactory.newInstance(); System.out.println("ROOTS="+roots.size()); for(Long k:new TreeSet<Long>(PHPCGFactory.call2mtd.keySet()))System.out.println("CALL "+k+" -> "+PHPCGFactory.call2mtd.get(k));
  ArrayList<FunctionDef> fs=new ArrayList<>(roots); fs.sort(Comparator.comparingLong(FunctionDef::getNodeId));
  for(FunctionDef f:fs){ if(!PHPCGFactory.returnTaintAnalyzed.contains(f.getNodeId())) continue; ParameterList pl=f.getParameterList(); Set<Integer> ps=PHPCGFactory.returnTaintPositions.get(f.getNodeId()); ArrayList<String> names=new ArrayList<>(); if(pl!=null) for(int i=0;i<pl.size();i++) names.add(((Parameter)pl.getParameter(i)).getName()); System.out.println("RET "+f.getNodeId()+" "+f.getName()+" params="+names+" positions="+(ps==null?Collections.emptySet():ps)); }
  System.out.println("DDG_RELS"); for(Long k:new TreeSet<Long>(DDG.rels.keySet())) for(Pair<Long,String> p:DDG.rels.get(k)) System.out.println("DDG "+k+" -> "+p.getL()+" var="+p.getR()); }}
